INSERT INTO `areaclic` VALUES ('mdCintura','Circunferncia da cintura','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Circunfer\\\'eancia da cintura\\plain\\f3\\fs22 \r\n\\par \r\n\\par Para a circunfer\\\'eancia de cintura, a fita m\\\'e9trica dever\\\'e1 ser posicionada no plano horizontal, ao n\\\'edvel natural da cintura, isto \\\'e9, no ponto coincidente com a dist\\\'e2ncia m\\\'e9dia entre a \\\'faltima costela e a \\plain\\f3\\fs22\\ul crista-il\\\'edaca\\plain\\f3\\fs22 . A medida dever\\\'e1 ser obtida ao final de uma \\plain\\f3\\fs22\\ul expira\\\'e7\\\'e3o\\plain\\f3\\fs22  normal, sem a compress\\\'e3o da pele. O avaliador dever\\\'e1 postar-se \\\'e0 frente do avaliado.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',1);